#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>

int main(int argc, char **argv)
{
    /* ----- no argument --------------------------------------------------- */
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }

    /* ----- parse the argument ------------------------------------------- */
    char *endptr = NULL;
    long n = strtol(argv[1], &endptr, 10);

    /* parsing failed (no digits) or extra characters after the number */
    if (endptr == argv[1] || *endptr != '\0') {
        puts("BAD_INPUT");
        return 0;
    }

    /* negative numbers are not accepted */
    if (n < 0) {
        puts("BAD_INPUT");
        return 0;
    }

    /* ----- special cases ------------------------------------------------- */
    if (n == 0) {
        puts("EMPTY");
        return 0;
    }

    if (n > 60) {                 /* 0x3c == 60, the limit used by the binary */
        puts("OUT_OF_RANGE");
        return 0;
    }

    /* ----- generate and print Pascal's triangle -------------------------- */
    long long row[61] = {0};
    row[0] = 1;                   /* first row */

    for (int i = 0; i < n; ++i) {
        /* print current row */
        for (int j = 0; j <= i; ++j) {
            if (j) putchar(' ');
            printf("%lld", row[j]);
        }
        putchar('\n');

        /* compute next row in‑place (right‑to‑left) */
        row[i + 1] = 1;           /* new rightmost 1 */
        for (int j = i; j > 0; --j) {
            row[j] = row[j] + row[j - 1];
        }
        /* row[0] stays 1 automatically */
    }

    return 0;
}
